export function translateRaw(locale: Locale, value: string): string {
    if (/^(?:common|gallery|stats|faq|portfolio|footer)\./u.test(value.trim())) return "";
    if (locale !== "en") return thaiRawMessages[value] ?? value;
    if (!/[ก-๙]/u.test(value)) return value;
    const leading = value.match(/^\s*/)?.[0] ?? "";
    const trailing = value.match(/\s*$/)?.[0] ?? "";
    const core = value.slice(leading.length, value.length - trailing.length || undefined);
    // The existing dictionary was authored with a UTF-8/Latin-1 encoding
    // mismatch. Keep its source values untouched, but repair keys at lookup
    // time so the Thai source text remains byte-for-byte unchanged.
    const repairedCore = repairMojibake(core);
    const normalizedRepairedCore = repairedCore.replace(/\s+/gu, " ").trim();
    const direct = rawMessages[core] ?? rawMessages[repairedCore] ?? rawMessages[normalizedRepairedCore];
    if (direct) return `${leading}${direct}${trailing}`;
    // Never apply a unit conversion to a sentence. The old fallback used
    // bare suffix replacements, which turned phrases such as "ทุกคน" into
    // corrupted mixed-language text. Dynamic unit strings are handled only
    // when the complete value is numeric.
    if (/[\u0e04\u0e19]$|[\u0e23\u0e39\u0e1b]$|[\u0e19]\.$/u.test(repairedCore) && !/^\d+\s*/u.test(repairedCore)) {
        return value;
    }
    const dynamic = repairedCore
        .replace(/^เปิด Portfolio (\d+)$/u, "Open portfolio $1")
        .replace(/^เปิดรูปที่ (\d+)$/u, "Open image $1")
        .replace(/^เลื่อนรูป (\d+) ขึ้น$/u, "Move image $1 up")
        .replace(/^เลื่อนรูป (\d+) ลง$/u, "Move image $1 down")
        .replace(/เป็นไฟล์ว่างเปล่า$/u, " is an empty file")
        .replace(/ไม่ใช่ไฟล์รูปภาพที่รองรับ$/u, " is not a supported image file")
        .replace(/มีขนาดเกิน 20MB$/u, " exceeds 20MB")
        .replace(/ไม่รองรับ หรือมีขนาดเกิน 20MB$/u, " is unsupported or exceeds 20MB")
        .replace(/คน$/u, "people")
        .replace(/รายการ$/u, "items")
        .replace(/ชิ้น$/u, "pieces")
        .replace(/รูป$/u, "photos")
        .replace(/ชั่วโมง$/u, "hours")
        .replace(/น\.$/u, "min.");
    return `${leading}${dynamic}${trailing}`;
}
